  clean = clean.replace(/[\u0400-\u04FF]/g, (ch) => {
    const homoglyphs = {
      "\u0430": "a",
      "\u0435": "e",
      "\u043E": "o",
      "\u0440": "p",
      "\u0441": "c",
      "\u0443": "y",
      "\u0410": "A",
      "\u0415": "E",
      "\u041E": "O",
      "\u0420": "P",
      "\u0421": "C",
      "\u0423": "Y"
    };
    return homoglyphs[ch] || ch;
  });
