  const guarded = ["depende", "no estoy seguro", "tal vez", "quiz\xE1s", "puede ser", "no s\xE9 si"];
  const accion = ["podr\xEDamos", "deber\xEDamos", "propongo", "qu\xE9 tal si", "se podr\xEDa", "hagamos", "hay que cambiar", "una soluci\xF3n", "implementar"];
